#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <inttypes.h>

int main(int argc, char *argv[])
{
    if (argc < 4) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr;
    long long base, exp, mod;
    base = strtoll(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    exp = strtoll(argv[2], &endptr, 10);
    if (endptr == argv[2] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    mod = strtoll(argv[3], &endptr, 10);
    if (endptr == argv[3] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (mod < 1) {
        puts("BAD_MODULUS");
        return 0;
    }
    if (mod > 1000000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (exp < 0) {
        puts("NEGATIVE_EXPONENT");
        return 0;
    }
    base %= mod;
    if (base < 0) base += mod;
    unsigned __int128 result = 1 % (unsigned __int128)mod;
    unsigned __int128 b = (unsigned __int128)base;
    unsigned __int128 m = (unsigned __int128)mod;
    while (exp > 0) {
        if (exp & 1LL) {
            result = (result * b) % m;
        }
        b = (b * b) % m;
        exp >>= 1;
    }
    printf("result=%" PRId64 "\n", (int64_t)result);
    return 0;
}
